'use client'

import * as React from 'react'

// stat renders the number, the label, the change beside it and the accessible
// name. This file adds the flame and nothing else.
import { Stat, type StatPresentation } from './stat'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Streak, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './streak.css'

/**
 * Streak: how many in a row, drawn as a flame.
 *
 * A thin wrapper over `stat` (BDS-021). It renders no number of its own, owns
 * no tabular numerals and invents no accessible-name vocabulary: `data-gs-value`,
 * `data-gs-delta`, the label and the announcement all come from `stat`. What
 * streak adds is the flame, which is lit while the run is alive and out once it
 * is not.
 *
 * A broken streak is `value={0}`, which is a real state and reads like every
 * other zero: `data-gs-value="0"`, announced as "streak, 0". There is no
 * separate broken attribute, because the number already says it and a second
 * name for one fact drifts from the first.
 *
 * A streak carries no `max`, deliberately. It has no ceiling, so there is
 * nothing for `data-gs-max` to hold and "7 of 7" would read as complete.
 *
 * It performs nothing. It does not count, break, or decide when a streak is
 * about to go. The host owns the number.
 */

export interface StreakProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** How many in a row. Zero is a broken streak, which is a state. */
  value: number
  /** How much it just moved, signed. One more in a row is `1`. */
  delta?: number
  /** About to go. The host decides where that line is. */
  critical?: boolean
  /** The word beside the flame. Defaults to "streak". */
  label?: string
  /**
   * The silhouette of the number inside. The design draws the streak as a pill
   * rather than as a label above a bare number (GSUI-100); the flame sits beside
   * it either way.
   */
  presentation?: StatPresentation
}

/**
 * Two drawings, not one drawing in two colours.
 *
 * A lit streak is a solid flame. A broken one is the same silhouette left
 * hollow with a wisp curling off it, so outline, fill and stroke count all
 * differ and a player who cannot see the orange still sees that it went out.
 */
const FLAME =
  'M12 2.5c4 4 6 7.1 6 9.5a6 6 0 0 1-12 0c0-1.8.8-3.5 2.4-5.2.1 1.4.7 2.4 1.8 3 .6-2.6.5-4.9-.2-7.3z'

const WISP = 'M12 6.4c-1.6 1.7-1.4 3 .2 4.1 1.5 1.1 1.7 2.4.3 4'

function Flame({ out }: { out: boolean }) {
  return (
    <svg
      className={['gs-streak__flame', out ? 'gs-streak__flame--out' : null]
        .filter(Boolean)
        .join(' ')}
      viewBox="0 0 24 24"
      focusable="false"
      aria-hidden="true"
    >
      {/* currentColor throughout: the flame names no colour, so a theme owns it
          and the shape owns the meaning. */}
      <path d={FLAME} fill={out ? 'none' : 'currentColor'} stroke="currentColor" />
      {out ? <path d={WISP} fill="none" stroke="currentColor" /> : null}
    </svg>
  )
}

export function Streak({
  value,
  delta,
  critical,
  label,
  presentation = 'pill',
  className,
  ...rest
}: StreakProps) {
  return (
    <div
      {...rest}
      className={['gs-streak', className].filter(Boolean).join(' ')}
      data-gs-component="streak"
    >
      <Stat
        kind="streak"
        label={label}
        value={value}
        delta={delta}
        critical={critical}
        presentation={presentation}
      />
      {/*
        The reserved `glyph` part: the state carried without colour. Stat renders
        a glyph of its own when critical, nested inside itself, so a test reaches
        this one as a direct child of the streak root and the two never collide.

        `emphasis`, not `motion`: the flame changes shape and colour and never
        moves, so it survives reduced motion, which is the whole point of
        drawing it.
      */}
      <span
        className="gs-streak__glyph"
        data-gs-scope="streak" data-gs-part="glyph"
        data-gs-animates="emphasis"
        aria-hidden="true"
      >
        <Flame out={value <= 0} />
      </span>
    </div>
  )
}

/* Streak. Every value comes from a token; nothing here is a literal colour.
   The number, its label and its change are stat's; this file lays out the
   flame and nothing else. */

/* The flame belongs inside the pill.

   It is a sibling of the stat in the DOM, deliberately: stat renders a glyph of
   its own when a value turns critical, and keeping the flame outside is what
   stops a test reaching for one and finding the other. Left to itself, though,
   that DOM drew the flame floating beside the pill with nothing around it, and
   in the game's HUD it read as an icon that had come loose.

   So the streak root carries the pill and the stat inside it gives its own up.
   One shape, both things in it, and the parts stay where the contract says.

   Only when the stat is actually a pill: in the plain presentation there is no
   shape to be inside, and drawing one here would invent a chip the host did not
   ask for. */
.gs-streak {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-2);
}

.gs-streak:has(.gs-stat[data-gs-presentation='pill']) {
  position: relative;
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-surface-raised);
  padding-inline-end: var(--gs-space-4);
  min-block-size: var(--gs-size-action);
}

.gs-streak:has(.gs-stat[data-gs-presentation='pill']) .gs-stat[data-gs-presentation='pill'] {
  background: none;
  padding-inline-end: 0;
}

.gs-streak__glyph {
  display: inline-flex;
  align-items: center;
  color: var(--gs-color-warning);
  /* Emphasis: colour only, no movement, so it still reads under reduced
     motion. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-streak__flame {
  display: block;
  width: var(--gs-size-icon-control);
  height: var(--gs-size-icon-control);
  stroke-width: var(--gs-stroke-ui);
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* A streak that went out is hollow, smoking and muted. The first two survive a
   colour blind player, a greyscale screenshot and a printed page; the third is
   the part nobody has to rely on. */
.gs-streak__flame--out {
  color: var(--gs-color-muted);
}
